{
  "description": "The creature is a large upright-standing chimera shown in profile facing right, with the head and shaggy mane of a lion on top, a spotted feline body and hindquarters, and two large outstretched feathered wings in place of forelimbs. Its upper chest and neck are covered in overlapping brown and tan feathers, its lower torso, hind legs and long tail are covered in tawny fur with dark rosette spots, and it stands on two muscular hind legs with its wings spread wide to the sides.",
  "parts": [
    {
      "part": "head",
      "looks_like": "lion-like head with tawny fur, yellow eyes, a dark pink-brown nose, white fur on the muzzle and chin, and small dark whisker spots",
      "where": "at the top front of the body, facing right in profile"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with light brown fur and darker inner shading",
      "where": "on top of the head, set into the mane, one more visible than the other"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, layered mane of long hair in shades of light tan to dark brown with a tousled texture",
      "where": "encircling the head, neck, and extending down to the upper chest"
    },
    {
      "part": "legs",
      "looks_like": "two thick muscular hind legs covered in tawny fur with dark brown rosette spots",
      "where": "at the lower middle and rear of the body, supporting the body in an upright bipedal stance"
    },
    {
      "part": "feet",
      "looks_like": "large paw-like feet with rounded toes and short blunt claws, covered in spotted fur",
      "where": "at the bottom ends of the two hind legs, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "long slender tail covered in spotted tawny fur with a dark brown to black tuft at the tip, curved in a U-shape",
      "where": "extending from the rear of the hindquarters, curving down then up"
    },
    {
      "part": "wings",
      "looks_like": "two large broad wings with layered feathers in tan, light brown and dark brown, with darker tips on the outer primaries",
      "where": "attached to the sides of the upper back and chest, spread outward to the left and right"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping leaf-shaped feathers in brown and tan with darker brown tips on the lower chest, and long flight feathers on the wings",
      "where": "covering both wings and the front of the neck and chest down to the upper belly"
    },
    {
      "part": "markings",
      "looks_like": "dark brown and black rosette and solid spots of varying size on a tan background",
      "where": "covering the torso, hind legs, and tail, denser on the back and sides and lighter on the belly"
    }
  ],
